import { Component, computed, inject, input } from '@angular/core';
import { rxResource } from '@angular/core/rxjs-interop';
import { RouterLink } from '@angular/router';
import { ProjectInvoices } from '../invoices/project-invoices';
import { ProjectService } from './project.service';

// A single project's page: its name and client, and its invoices.
@Component({
  selector: 'app-project-detail',
  imports: [RouterLink, ProjectInvoices],
  template: `
    <a routerLink="/projects" data-testid="project-back">Back to projects</a>
    @if (project.error()) {
      <p role="alert" data-testid="project-error">Could not load the project.</p>
    } @else if (project.value(); as p) {
      <h1 data-testid="project-detail-name">{{ p.name }}</h1>
      <p>Client: <span data-testid="project-detail-client">{{ p.clientName }}</span></p>
      <app-project-invoices [projectId]="projectId()" />
    }
  `,
})
export class ProjectDetail {
  private readonly service = inject(ProjectService);

  /** Bound from the `:id` route parameter. */
  readonly id = input.required<string>();
  protected readonly projectId = computed(() => Number(this.id()));

  protected readonly project = rxResource({
    params: () => this.projectId(),
    stream: ({ params }) => this.service.get(params),
  });
}
import { Component, inject, input, output, signal } from '@angular/core';
import { rxResource } from '@angular/core/rxjs-interop';
import { NonNullableFormBuilder, ReactiveFormsModule, Validators } from '@angular/forms';
import { Contact, ContactService } from './contact.service';

type ContactField = 'name' | 'email' | 'role';

// A client's contacts: add a contact (name, email, role) and list the contacts kept for that client.
@Component({
  selector: 'app-client-contacts',
  imports: [ReactiveFormsModule],
  template: `
    <section aria-labelledby="client-contacts-heading" data-testid="client-contacts">
      <h2 id="client-contacts-heading">Contacts</h2>

      <form [formGroup]="form" (ngSubmit)="submit()" data-testid="contact-form" novalidate>
        <div>
          <label for="contact-name">Name</label>
          <input
            id="contact-name"
            type="text"
            formControlName="name"
            autocomplete="name"
            data-testid="contact-form-name"
            [attr.aria-invalid]="showError('name')"
            [attr.aria-describedby]="showError('name') ? 'contact-name-error' : null"
          />
          @if (showError('name')) {
            <p id="contact-name-error" role="alert" data-testid="contact-form-name-error">
              Name is required.
            </p>
          }
        </div>
        <div>
          <label for="contact-email">Email</label>
          <input
